<?php
namespace App\Services;
use App\Models\FinancialActivity; use App\Models\User; use App\Models\Wallet; use App\Models\WalletTransaction; use App\Models\InternalTransfer; use Illuminate\Support\Str;
class FinancialActivityService {
 public function reference(string $prefix): string { return strtoupper($prefix).'-'.now()->format('YmdHis').'-'.strtoupper(Str::random(6)); }
 public function snapshot(Wallet $wallet): array { $wallet->refresh(); return ['balance'=>(float)$wallet->balance,'available'=>(float)$wallet->available_balance,'reserved'=>(float)$wallet->reserved_balance]; }
 public function record(User $user,string $eventType,string $title,?string $description=null,?string $reference=null,?string $status=null,?string $direction=null,?float $amount=null,?Wallet $wallet=null,?WalletTransaction $walletTransaction=null,?InternalTransfer $internalTransfer=null,array $before=[],array $metadata=[],string $actorType='system',?int $actorId=null): FinancialActivity { $wallet ??= $user->wallet; $after=$wallet?$this->snapshot($wallet):['balance'=>null,'available'=>null,'reserved'=>null]; return FinancialActivity::create(['user_id'=>$user->id,'wallet_id'=>$wallet?->id,'wallet_transaction_id'=>$walletTransaction?->id,'internal_transfer_id'=>$internalTransfer?->id,'reference'=>$reference??$walletTransaction?->reference_id,'event_type'=>$eventType,'title'=>$title,'description'=>$description,'status'=>$status,'direction'=>$direction,'amount'=>$amount,'balance_before'=>$before['balance']??null,'balance_after'=>$after['balance'],'available_before'=>$before['available']??null,'available_after'=>$after['available'],'reserved_before'=>$before['reserved']??null,'reserved_after'=>$after['reserved'],'actor_type'=>$actorType,'actor_id'=>$actorId,'metadata'=>$metadata?:null]); }
}
